void binary_insertion_sort(int a[], int n) {
    for (int i = 1; i < n; i++) {
        int key = a[i];
        int lo = 0, hi = i;              /* find first index with a > key */
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] <= key) lo = mid + 1;
            else hi = mid;
        }
        memmove(&a[lo + 1], &a[lo], (size_t)(i - lo) * sizeof a[0]);
        a[lo] = key;
    }
}

struct node { int val; struct node *next; };

struct node *insertion_sort_list(struct node *head) {
    struct node dummy = {0, NULL};          /* sorted output list */
    while (head) {
        struct node *next = head->next;
        struct node *p = &dummy;
        while (p->next && p->next->val <= head->val)
            p = p->next;                    /* stop before first greater */
        head->next = p->next;
        p->next = head;
        head = next;
    }
    return dummy.next;
}
